function Restore-NvidAppPayload {
    param([string]$ExtractRoot)

    $sourceRoot = Join-Path $ExtractRoot 'NvApp'
    if (-not (Test-Path $sourceRoot)) {
        throw ("Official NVIDIA App payload folder is missing: {0}" -f $sourceRoot)
    }

    $targetRoot = 'C:\Program Files\NVIDIA Corporation\NVIDIA App'
    $containerService = Get-Service -Name 'NvContainerLocalSystem' -ErrorAction SilentlyContinue
    if ($containerService -and $containerService.Status -eq 'Running') {
        Stop-Service -Name 'NvContainerLocalSystem' -Force -ErrorAction SilentlyContinue
        Start-Sleep -Seconds 2
    }

    Get-Process -ErrorAction SilentlyContinue |
        Where-Object {
            $_.Path -like 'C:\Program Files\NVIDIA Corporation\NVIDIA App*' -or
            $_.Path -like 'C:\Program Files\NVIDIA Corporation\NvContainer*'
        } |
        ForEach-Object {
            Stop-Process -Id $_.Id -Force -ErrorAction SilentlyContinue
        }
    Start-Sleep -Seconds 2

    New-Item -ItemType Directory -Path $targetRoot -Force | Out-Null
    Copy-Item -Path (Join-Path $sourceRoot '*') -Destination $targetRoot -Recurse -Force

    $targetExe = Join-Path $targetRoot 'CEF\NVIDIA App.exe'
    if (-not (Test-Path $targetExe)) {
        throw ("Restored NVIDIA App payload but the launch path is still missing: {0}" -f $targetExe)
